class.description:
[SaveManager] est une classe utilitaire statique : elle ne s'instancie pas, toutes ses méthodes s'appellent directement sur la classe.
Elle s'appuie sur [SaveFileAccess] pour l'accès au disque et écrit le résultat de chaque opération dans le journal ([CustomLogger]).
[codeblock]
var sauvegarde: SaveData = preload("res://sauvegardes/joueur.tres")
sauvegarde.data["vie"] = 80
SaveManager.save(sauvegarde, sauvegarde.file_config)

var chargee := SaveManager.load(sauvegarde, sauvegarde.file_config)
if chargee:
    sauvegarde.data = chargee.data
[/codeblock]
